  const jIconImages=__CATEGORY_IMAGE_DATA__;
  Object.assign(state,{jCustomIcons:{饮品:jIconImages.coffee,奶茶:jIconImages.milk},jCustomIconFits:{饮品:'contain',奶茶:'contain'},jIconMode:'preset',jIconImage:jIconImages.milk,jIconFit:'contain',jIconOverrides:{}});
  const jSubIconDefinitions={早餐:'sunrise',午餐:'utensils',晚餐:'moon',零食:'cookie',咖啡:'coffee',奶茶:'cup-soda',酒水:'wine',公交地铁:'train-front',打车:'car-taxi-front',燃油:'fuel',停车:'square-parking',日用品:'shopping-basket',服饰:'shirt',生鲜:'carrot',房租:'house',水电:'droplets',物业:'building',电影:'clapperboard',游戏:'gamepad-2',旅行:'plane',书籍:'book-open',课程:'graduation-cap',门诊:'stethoscope',药品:'pill',礼物:'gift',红包:'mail',设备:'laptop',软件:'app-window',健身:'dumbbell',装备:'footprints',宠粮:'bone',洗护:'bath'};
  function jCategoryVisual(name,fallback='shapes'){const image=state.jCustomIcons[name];return image?`<img class="j-category-image" src="${esc(image)}" alt="${esc(name)}自定义图片" data-icon-category="${esc(name)}" data-fit="${state.jCustomIconFits[name]||'contain'}">`:icon(state.jIconOverrides[name]||jSubIconDefinitions[name]||fallback);}
  function gOriginalCategoryGrid(limit=7){const list=state.recordType==='income'?incomes:pAllCategories.slice(0,limit).concat([['更多分类','grid-2x2']]);let html='';for(let start=0;start<list.length;start+=4){const row=list.slice(start,start+4);html+=`<div class="p-category-row">${row.map(([n,i])=>{const extra=n==='更多分类'&&!pAllCategories.slice(0,limit).some(([name])=>name===state.category);return btn(n==='更多分类'?'p-morecategories':`p-parent:${n}`,`<span class="bc-entry-icon">${jCategoryVisual(n,i)}${pCategoryTree[n]||extra?'<span class="p-cat-chevron"></span>':''}</span><span>${n}</span>${extra?`<small class="w-more-selected">${esc(state.category)}</small>`:''}`,n,'p-category',`aria-pressed="${state.category===n||extra}" ${pCategoryTree[n]?`aria-expanded="${state.expandedCategory===n}"`:''}`);}).join('')}</div>`;if(state.fSeedMode!=='flat'&&row.some(([n])=>n===state.expandedCategory)&&pCategoryTree[state.expandedCategory])html+=`<div class="p-subcategories j-subcategories" aria-label="${state.expandedCategory}二级分类">${btn(`p-sub:${state.expandedCategory}:`,`${jCategoryVisual(state.expandedCategory,'shapes')}<span>${esc(state.expandedCategory)}</span>`,'仅选择'+state.expandedCategory,'',`aria-pressed="${!state.subcategory}"`)}${pCategoryTree[state.expandedCategory].map(n=>btn(`p-sub:${state.expandedCategory}:${n}`,`${jCategoryVisual(n)}<span>${esc(n)}</span>`,'选择'+n,'',`aria-pressed="${state.subcategory===n}"`)).join('')}</div>`;}return html;}
  function jIconPreview(image,fit='contain',status='ready'){return `<span class="j-icon-preview" data-fit="${fit}" data-state="${status}">${status==='loading'?'<span class="j-icon-loading"></span>':status==='error'?icon('shapes'):`<img src="${esc(image)}" alt="自定义分类图片预览">`}</span>`;}
  function jCategoryIconExamples(){return `${surface(`<h3>一级与二级分类</h3><p class="bc-small" style="margin:8px 0 18px">同一套图标容器，保留自定义图片原色。</p><div class="j-icon-examples">${[['餐饮','utensils'],['饮品','coffee'],['咖啡','coffee'],['奶茶','cup-soda']].map(([n,i])=>`<div><span class="bc-entry-icon">${jCategoryVisual(n,i)}</span><span>${n}</span><small>${state.jCustomIcons[n]?'自定义图片':'预设图标'}</small></div>`).join('')}</div>`)}${surface(`<h3>图片适配与异常状态</h3><div class="j-icon-examples">${[[jIconImages.milk,'contain','ready','透明 PNG'],[jIconImages.photo,'cover','ready','方形裁切'],['','contain','loading','加载中'],['','contain','error','加载失败']].map(([image,fit,status,title])=>`<div>${jIconPreview(image,fit,status)}<span>${title}</span></div>`).join('')}</div><p class="bc-small" style="margin-top:16px">图片不随主题色着色；选中态由容器和勾选表达。</p>`)}${fCTA('f-go:category-edit','编辑分类图标')}`;}
  fDefine('category-icons','分类图标与自定义图片','交互补充','category/category_edit_page.dart',jCategoryIconExamples);
  fDefs['category-edit'].body=()=>`${surface(`${fInput('categoryName','分类名称',state.dSub||state.dCategory||'奶茶','text','输入分类名称',true)}${fSelect('categoryKind','分类类型',['支出','收入'],'支出')}<div class="f-row-grid">${fSelect('categoryLevel','分类层级',['一级分类','二级分类'],'二级分类')}${fSelect('categoryParent','所属一级分类',pAllCategories.map(([n])=>n),'饮品')}</div>`)}${surface(`<div class="bc-between"><h3>分类图标</h3><span class="bc-small">支持自定义图片</span></div><div class="bc-segment j-icon-tabs" aria-label="图标来源">${[['preset','预设图标'],['custom','自定义图片']].map(([v,n])=>btn('j-icon-mode:'+v,n,n,'',`aria-pressed="${state.jIconMode===v}"`)).join('')}</div>${state.jIconMode==='preset'?`<div class="f-icon-grid">${['utensils','coffee','cup-soda','train-front','shopping-basket','house','heart-pulse','gift','laptop','dumbbell','paw-print','book-open'].map(i=>btn('f-icon:'+i,icon(i),'选择'+i+'图标','',`aria-pressed="${state.fIcon===i}"`)).join('')}</div>`:`<div class="j-custom-preview">${jIconPreview(state.jIconImage,state.jIconFit)}<div><h3>1:1 图标预览</h3><p>保留图片原色与透明背景</p></div></div><label class="f-field">选择图片<input type="file" accept="image/png,image/jpeg,image/webp" data-j-custom-file aria-label="上传自定义分类图片"></label><div class="p-chips">${[['contain','完整显示'],['cover','填满裁切']].map(([v,n])=>btn('j-icon-fit:'+v,n,n,'p-chip',`aria-pressed="${state.jIconFit===v}"`)).join('')}</div><div class="j-icon-sample-options">${btn('j-icon-example:milk','透明图片示例','预览透明图标','f-inline-button')}${btn('j-icon-example:photo','方形图片示例','预览方形裁切','f-inline-button')}</div>`}`)}${fCTA('j-save-category','保存分类')}${fLink('category-icons','image','查看图标展示规范')}${fLink('category-migration','arrow-right-left','迁移此分类账单')}${fCTA('f-confirm:删除分类','删除分类')}`;
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [action,...parts]=el.dataset.action.split(':'),arg=parts.join(':');if(!['j-icon-mode','j-icon-fit','j-icon-example','j-save-category'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(action==='j-icon-mode'){state.jIconMode=arg;render();}else if(action==='j-icon-fit'){state.jIconFit=arg;render();}else if(action==='j-icon-example'){state.jIconImage=jIconImages[arg];state.jIconFit=arg==='photo'?'cover':'contain';render();}else{if(!fValidate())return;const name=fVal('categoryName',state.dSub||state.dCategory||'奶茶');if(state.jIconMode==='custom'){state.jCustomIcons[name]=state.jIconImage;state.jCustomIconFits[name]=state.jIconFit;}else{delete state.jCustomIcons[name];state.jIconOverrides[name]=state.fIcon;}fResult('分类已保存','图标已同步到分类选择与详情。','categories');}persist();},true);
  root.addEventListener('change',e=>{if(!e.target.matches('[data-j-custom-file]'))return;const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.addEventListener('load',()=>{state.jIconImage=String(reader.result);render();});reader.readAsDataURL(file);});
  root.addEventListener('error',e=>{const img=e.target;if(img instanceof HTMLImageElement&&img.classList.contains('j-category-image')){const fallback=document.createElement('span');fallback.className='j-image-fallback';fallback.innerHTML=icon('shapes');img.replaceWith(fallback);if(globalThis.lucide)globalThis.lucide.createIcons({attrs:{width:20,height:20}});}},true);
